/**
 * Browser half of @ds-hu/dsh-task-manager.
 *
 * Registers two slots on the Harness page:
 *  - `sidebar.panellist` → the left-sidebar entry (`任务管理器` / `Task Manager`);
 *  - `main` keyed `task-manager` → the full Win11-style panel.
 *
 * The bundle is generated by scripts/build-client.mjs; keep factories free of
 * side effects and put every registration inside `apply`.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import { createApi, useHistory, useNavCollapsed, usePanelWidth, usePoll, useSettings } from './data.js';
import { EndTaskDialog, PropertiesDialog, SettingsDialog } from './dialogs.jsx';
import { createFormatters } from './format.js';
import { dictionaries, en, format, NS } from './i18n.js';
import { IconCopy, IconEndTask, IconInfo, IconTaskManager } from './icons.jsx';
import { PerformancePage } from './pages/performance.jsx';
import { ProcessesPage } from './pages/processes.jsx';
import { AppHistoryPage, DetailsPage, ServicesPage, StartupPage, UsersPage } from './pages/tables.jsx';
import { NavRail, TitleBar } from './shell.jsx';
import { ensureStyles } from './styles.js';
import { PopupMenu } from './ui.jsx';

const PANEL_ID = 'task-manager';
const API_BASE = '/dsh-task-manager/api';

/** Services required by this client half. */
export const inject = ['slots', 'locale', 'theme'];

/**
 * Locale + dictionary store. `t` is stable and reads the live locale, which is
 * what the sidebar label thunk needs.
 * @param {any} ctx - Client context.
 * @returns {{ t: (key: string, vars?: Record<string, string | number>) => string, subscribe: (listener: () => void) => () => void, getSnapshot: () => string }} the i18n face.
 */
function createI18n(ctx) {
  let active = ctx.locale.getLocale().active;
  const listeners = new Set();
  const update = () => {
    const next = ctx.locale.getLocale().active;
    if (next === active) return;
    active = next;
    for (const listener of listeners) listener();
  };
  ctx.effect(() => ctx.locale.subscribe(update), 'task-manager: locale changes');

  const t = (key, vars) => {
    const dict = dictionaries[active] ?? dictionaries.en ?? en;
    const template = dict[key] ?? en[key] ?? key;
    return vars === undefined ? template : format(template, vars);
  };

  return {
    t,
    getSnapshot: () => active,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/**
 * Host theme store: `light` / `dark`, following `theme/change`.
 * @param {any} ctx - Client context.
 * @returns {{ getSnapshot: () => string, subscribe: (listener: () => void) => () => void }} the theme face.
 */
function createTheme(ctx) {
  let scheme = ctx.theme.getTheme().active.colorScheme;
  const listeners = new Set();
  const update = () => {
    const next = ctx.theme.getTheme().active.colorScheme;
    if (next === scheme) return;
    scheme = next;
    for (const listener of listeners) listener();
  };
  ctx.effect(() => ctx.on('theme/change', update), 'task-manager: theme changes');

  return {
    getSnapshot: () => scheme,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/**
 * Render the active page.
 * @param {any} props - page routing props.
 * @returns {any} the page element.
 */
function renderPage(props) {
  const common = {
    t: props.t,
    fmt: props.fmt,
    snapshot: props.snapshot,
    loading: props.loading,
    error: props.error,
    onRefresh: props.onRefresh,
    settings: props.settings,
    selectedPid: props.selectedPid,
    onSelect: props.onSelect,
    onEndTask: props.onEndTask,
    onProperties: props.onProperties,
    onContextMenu: props.onContextMenu,
  };

  switch (props.page) {
    case 'performance':
      return (
        <PerformancePage
          t={props.t}
          fmt={props.fmt}
          snapshot={props.snapshot}
          system={props.system}
          scheme={props.scheme}
          history={props.history}
          loading={props.loading}
          error={props.error}
          onRefresh={props.onRefresh}
        />
      );
    case 'appHistory':
      return (
        <AppHistoryPage
          t={props.t}
          fmt={props.fmt}
          history={props.appHistory}
          loading={props.appHistoryLoading}
          error={props.appHistoryError}
          onRefresh={props.onRefresh}
        />
      );
    case 'startup':
      return (
        <StartupPage
          t={props.t}
          startup={props.startup}
          loading={props.startupLoading}
          error={props.startupError}
          onRefresh={props.onRefresh}
        />
      );
    case 'users':
      return (
        <UsersPage
          t={props.t}
          fmt={props.fmt}
          snapshot={props.snapshot}
          loading={props.loading}
          error={props.error}
          onRefresh={props.onRefresh}
        />
      );
    case 'details':
      return <DetailsPage {...common} />;
    case 'services':
      return (
        <ServicesPage
          t={props.t}
          fmt={props.fmt}
          services={props.services}
          loading={props.servicesLoading}
          error={props.servicesError}
          onRefresh={props.onRefresh}
        />
      );
    case 'processes':
    default:
      return <ProcessesPage {...common} />;
  }
}

/**
 * The panel component. Receives the injected `{ api, i18n, theme }` face.
 * @param {any} props - slot props.
 * @returns {any} the panel.
 */
function App(props) {
  const { i18n, theme, api } = props;
  const { t } = i18n;
  const scheme = useSyncExternalStore(theme.subscribe, theme.getSnapshot, theme.getSnapshot);
  const locale = useSyncExternalStore(i18n.subscribe, i18n.getSnapshot, i18n.getSnapshot);
  const fmt = useMemo(() => createFormatters(locale, t), [locale, t]);

  const [settings, updateSettings] = useSettings();
  const { collapsed, toggle, refine } = useNavCollapsed();
  const rootRef = useRef(null);
  usePanelWidth(rootRef, refine);

  const [page, setPage] = useState('processes');
  const [selectedPid, setSelectedPid] = useState(null);
  const [menu, setMenu] = useState(null);
  const [dialog, setDialog] = useState(null);
  const [settingsOpen, setSettingsOpen] = useState(false);

  useEffect(() => {
    ensureStyles();
  }, []);

  const fetchSnapshot = useCallback((signal) => api.get('/snapshot', signal), [api]);
  const fetchSystem = useCallback((signal) => api.get('/system', signal), [api]);
  const fetchHealth = useCallback((signal) => api.get('/health', signal), [api]);
  const fetchServices = useCallback((signal) => api.get('/services', signal), [api]);
  const fetchStartup = useCallback((signal) => api.get('/startup', signal), [api]);
  const fetchAppHistory = useCallback((signal) => api.get('/history', signal), [api]);

  const snapshot = usePoll(fetchSnapshot, settings.refreshIntervalMs, true);
  const system = usePoll(fetchSystem, null, true);
  const health = usePoll(fetchHealth, null, true);
  const services = usePoll(fetchServices, 15000, page === 'services');
  const startup = usePoll(fetchStartup, 60000, page === 'startup');
  const appHistory = usePoll(fetchAppHistory, 15000, page === 'appHistory');
  const graphHistory = useHistory(snapshot.data);

  const refreshSnapshot = snapshot.refresh;
  const refreshServices = services.refresh;
  const refreshStartup = startup.refresh;
  const refreshAppHistory = appHistory.refresh;
  const refresh = useCallback(() => {
    refreshSnapshot();
    if (page === 'services') refreshServices();
    else if (page === 'startup') refreshStartup();
    else if (page === 'appHistory') refreshAppHistory();
  }, [page, refreshSnapshot, refreshServices, refreshStartup, refreshAppHistory]);

  const openEndTask = useCallback((process) => setDialog({ type: 'endTask', process }), []);
  const openProperties = useCallback((process) => setDialog({ type: 'properties', process }), []);
  const openContextMenu = useCallback((process, x, y) => setMenu({ process, x, y }), []);
  const closeDialog = useCallback(() => setDialog(null), []);
  const closeMenu = useCallback(() => setMenu(null), []);

  const copyName = useCallback((process) => {
    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard) navigator.clipboard.writeText(process.name);
    } catch {
      /* clipboard unavailable: the menu action is best effort */
    }
  }, []);

  const menuItems = useMemo(() => {
    if (menu === null) return [];
    return [
      {
        key: 'endTask',
        label: t('action.endTask'),
        icon: <IconEndTask size={16} />,
        danger: true,
        onSelect: () => openEndTask(menu.process),
      },
      {
        key: 'copy',
        label: t('action.copy'),
        icon: <IconCopy size={16} />,
        onSelect: () => copyName(menu.process),
      },
      { key: 'separator', separator: true },
      {
        key: 'properties',
        label: t('action.properties'),
        icon: <IconInfo size={16} />,
        onSelect: () => openProperties(menu.process),
      },
    ];
  }, [menu, t, openEndTask, openProperties, copyName]);

  const slow = snapshot.slow || services.slow || startup.slow || appHistory.slow;

  return (
    <div
      className="tm-root"
      data-theme={scheme}
      data-compact={settings.compactRows ? 'true' : 'false'}
      data-testid="tm-root"
      ref={rootRef}
      role="region"
      aria-label={t('panel')}
    >
      {slow ? <div className="tm-progress" aria-hidden="true" /> : null}
      <TitleBar t={t} onRefresh={refresh} onSettings={() => setSettingsOpen(true)} />
      <div className="tm-body">
        <NavRail
          t={t}
          page={page}
          collapsed={collapsed}
          onToggle={toggle}
          onNavigate={setPage}
          onSettings={() => setSettingsOpen(true)}
        />
        <div className="tm-content">
          {renderPage({
            page,
            t,
            fmt,
            scheme,
            snapshot: snapshot.data,
            loading: snapshot.loading,
            error: snapshot.error,
            system: system.data,
            history: graphHistory,
            appHistory: appHistory.data,
            appHistoryLoading: appHistory.loading,
            appHistoryError: appHistory.error,
            startup: startup.data,
            startupLoading: startup.loading,
            startupError: startup.error,
            services: services.data,
            servicesLoading: services.loading,
            servicesError: services.error,
            settings,
            selectedPid,
            onSelect: setSelectedPid,
            onEndTask: openEndTask,
            onProperties: openProperties,
            onContextMenu: openContextMenu,
            onRefresh: refresh,
          })}
        </div>
      </div>

      {menu !== null ? (
        <PopupMenu x={menu.x} y={menu.y} items={menuItems} onClose={closeMenu} testid="tm-context-menu" />
      ) : null}

      {dialog !== null && dialog.type === 'endTask' ? (
        <EndTaskDialog
          process={dialog.process}
          t={t}
          api={api}
          onClose={closeDialog}
          onDone={refreshSnapshot}
        />
      ) : null}

      {dialog !== null && dialog.type === 'properties' ? (
        <PropertiesDialog process={dialog.process} t={t} fmt={fmt} onClose={closeDialog} />
      ) : null}

      {settingsOpen ? (
        <SettingsDialog
          settings={settings}
          onChange={updateSettings}
          t={t}
          health={health.data}
          system={system.data}
          apiBase={API_BASE}
          onClose={() => setSettingsOpen(false)}
        />
      ) : null}
    </div>
  );
}

/** Left-rail glyph: a monitor with a waveform, 18px, currentColor. */
function PanelIcon(props) {
  return <IconTaskManager size={props.size ?? 18} />;
}

/**
 * Register both slots.
 * @param {any} ctx - Client context.
 * @returns {void}
 */
export function apply(ctx) {
  const i18n = createI18n(ctx);
  const theme = createTheme(ctx);
  const api = createApi();

  ctx.effect(() => ctx.locale.register(NS, dictionaries), 'task-manager: dictionaries');

  const injected = { api, i18n, theme };

  ctx.slots.inject('main', () =>
    ctx.slots.register(
      { name: 'main', key: PANEL_ID, locale: NS, inject: () => injected },
      App,
    ),
  );

  ctx.slots.inject('sidebar.panellist', () =>
    ctx.slots.register(
      {
        name: 'sidebar.panellist',
        id: PANEL_ID,
        order: 15,
        locale: NS,
        label: () => i18n.t('panel'),
      },
      PanelIcon,
    ),
  );
}
